-- WEB-070 dated operational inputs. No observed GPS, ownership transfer or agenda mutation.
CREATE TABLE visit_rep_planning_profile(
 id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),rep_id TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,revision_no INTEGER NOT NULL CHECK(revision_no>0),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),status TEXT NOT NULL DEFAULT 'current' CHECK(status IN('current','superseded','retired')),previous_id TEXT,config_json TEXT NOT NULL CHECK(json_valid(config_json) AND length(config_json)<=65536),config_sha256 TEXT NOT NULL CHECK(length(config_sha256)=64),reason TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,ended_at TEXT,
 UNIQUE(organization_id,id),UNIQUE(organization_id,rep_id,valid_from,valid_until,revision_no),FOREIGN KEY(organization_id,rep_id) REFERENCES app_user(organization_id,id),FOREIGN KEY(organization_id,previous_id) REFERENCES visit_rep_planning_profile(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES app_user(organization_id,id),CHECK(valid_from<=valid_until),CHECK((status='current')=(ended_at IS NULL))
);
CREATE INDEX visit_rep_planning_profile_dates ON visit_rep_planning_profile(organization_id,rep_id,status,valid_from,valid_until);
CREATE TRIGGER visit_rep_planning_profile_overlap BEFORE INSERT ON visit_rep_planning_profile WHEN NEW.status='current' AND EXISTS(SELECT 1 FROM visit_rep_planning_profile p WHERE p.organization_id=NEW.organization_id AND p.rep_id=NEW.rep_id AND p.status='current' AND p.valid_from<=NEW.valid_until AND p.valid_until>=NEW.valid_from) BEGIN SELECT RAISE(ABORT,'VISIT_PROFILE_DATE_OVERLAP');END;
CREATE TRIGGER visit_rep_planning_profile_guard BEFORE UPDATE ON visit_rep_planning_profile BEGIN
 SELECT CASE WHEN NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.rep_id<>OLD.rep_id OR NEW.valid_from<>OLD.valid_from OR NEW.valid_until<>OLD.valid_until OR NEW.revision_no<>OLD.revision_no OR NEW.config_json<>OLD.config_json OR NEW.config_sha256<>OLD.config_sha256 OR NEW.reason<>OLD.reason OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.previous_id IS NOT OLD.previous_id OR NEW.version<>OLD.version+1 OR OLD.status<>'current' OR NEW.status NOT IN('superseded','retired') THEN RAISE(ABORT,'VISIT_PROFILE_IMMUTABLE_OR_VERSION') END;
END;
CREATE TRIGGER visit_rep_planning_profile_no_delete BEFORE DELETE ON visit_rep_planning_profile BEGIN SELECT RAISE(ABORT,'VISIT_PROFILE_HISTORY_IMMUTABLE');END;
CREATE TRIGGER visit_rep_planning_profile_epoch_insert AFTER INSERT ON visit_rep_planning_profile BEGIN UPDATE visit_planning_revision SET source_epoch=source_epoch+1 WHERE organization_id=NEW.organization_id;END;
CREATE TRIGGER visit_rep_planning_profile_epoch_update AFTER UPDATE ON visit_rep_planning_profile BEGIN UPDATE visit_planning_revision SET source_epoch=source_epoch+1 WHERE organization_id=NEW.organization_id;END;
CREATE TRIGGER visit_rep_planning_profile_epoch_delete AFTER DELETE ON visit_rep_planning_profile BEGIN UPDATE visit_planning_revision SET source_epoch=source_epoch+1 WHERE organization_id=OLD.organization_id;END;
CREATE TABLE visit_customer_planning_profile(
 id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),customer_id TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,revision_no INTEGER NOT NULL CHECK(revision_no>0),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),status TEXT NOT NULL DEFAULT 'current' CHECK(status IN('current','superseded','retired')),previous_id TEXT,config_json TEXT NOT NULL CHECK(json_valid(config_json) AND length(config_json)<=65536),config_sha256 TEXT NOT NULL CHECK(length(config_sha256)=64),reason TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,ended_at TEXT,
 UNIQUE(organization_id,id),UNIQUE(organization_id,customer_id,valid_from,valid_until,revision_no),FOREIGN KEY(organization_id,customer_id) REFERENCES customer_outlet(organization_id,id),FOREIGN KEY(organization_id,previous_id) REFERENCES visit_customer_planning_profile(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES app_user(organization_id,id),CHECK(valid_from<=valid_until),CHECK((status='current')=(ended_at IS NULL))
);
CREATE INDEX visit_customer_planning_profile_dates ON visit_customer_planning_profile(organization_id,customer_id,status,valid_from,valid_until);
CREATE TRIGGER visit_customer_planning_profile_overlap BEFORE INSERT ON visit_customer_planning_profile WHEN NEW.status='current' AND EXISTS(SELECT 1 FROM visit_customer_planning_profile p WHERE p.organization_id=NEW.organization_id AND p.customer_id=NEW.customer_id AND p.status='current' AND p.valid_from<=NEW.valid_until AND p.valid_until>=NEW.valid_from) BEGIN SELECT RAISE(ABORT,'VISIT_PROFILE_DATE_OVERLAP');END;
CREATE TRIGGER visit_customer_planning_profile_guard BEFORE UPDATE ON visit_customer_planning_profile BEGIN
 SELECT CASE WHEN NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.customer_id<>OLD.customer_id OR NEW.valid_from<>OLD.valid_from OR NEW.valid_until<>OLD.valid_until OR NEW.revision_no<>OLD.revision_no OR NEW.config_json<>OLD.config_json OR NEW.config_sha256<>OLD.config_sha256 OR NEW.reason<>OLD.reason OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.previous_id IS NOT OLD.previous_id OR NEW.version<>OLD.version+1 OR OLD.status<>'current' OR NEW.status NOT IN('superseded','retired') THEN RAISE(ABORT,'VISIT_PROFILE_IMMUTABLE_OR_VERSION') END;
END;
CREATE TRIGGER visit_customer_planning_profile_no_delete BEFORE DELETE ON visit_customer_planning_profile BEGIN SELECT RAISE(ABORT,'VISIT_PROFILE_HISTORY_IMMUTABLE');END;
CREATE TRIGGER visit_customer_planning_profile_epoch_insert AFTER INSERT ON visit_customer_planning_profile BEGIN UPDATE visit_planning_revision SET source_epoch=source_epoch+1 WHERE organization_id=NEW.organization_id;END;
CREATE TRIGGER visit_customer_planning_profile_epoch_update AFTER UPDATE ON visit_customer_planning_profile BEGIN UPDATE visit_planning_revision SET source_epoch=source_epoch+1 WHERE organization_id=NEW.organization_id;END;
CREATE TRIGGER visit_customer_planning_profile_epoch_delete AFTER DELETE ON visit_customer_planning_profile BEGIN UPDATE visit_planning_revision SET source_epoch=source_epoch+1 WHERE organization_id=OLD.organization_id;END;
